function login() {
	   url="https://login.wlpc.com/"
    cookie.removeCookie(source.key)
    cookie.removeCookie(url)
    res = source.getLoginInfoMap()
    use=res.get("邮箱");
    pwd=res.get("密码");
    tk=java.ajax(url).match(/token" value="(.*)"/)[1]
    body=`token=${tk}&email=${use}&password=${pwd}&cmd=LOGIN`

   headers= {
    "Referer": url,
    "User-Agent": "Mozilla/5.0 (Linux; Android 15; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/133.0.0.9 Mobile Safari/537.36"
  }
        html=java.ajax(url+"index.php,"+JSON.stringify({
  "body": body,
  "method": "POST",
  "headers": JSON.stringify(headers)
    	}))
    	he=source.getCookie(url)
    	co=he.match(/c=(.*); x/)[1]
    	sa=he.match(/x=(.*); /)[1]
    	ck="cookie="+co+"; salt="+sa
    	source.putLoginHeader(ck)

}

